<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref} from 'vue'
import {useWorkspace} from '../../app/workspace'
import {createLatestRequests,isCancelled,RequestCancelled} from '../../shared/api/client'
import FormDialog from '../../shared/components/FormDialog.vue'
import Pagination from '../../shared/components/Pagination.vue'
import {formatTimestamp} from '../../shared/time'
import {template,type ClueRow} from './importSpreadsheet'
const emit=defineEmits<{imported:[]}>()
const {api,command,captureSession}=useWorkspace(),requests=createLatestRequests(api),input=ref<HTMLInputElement|null>(null)
const busy=ref(false),parsing=ref(false),error=ref(''),notice=ref(''),filename=ref(''),rows=ref<ClueRow[]>([]),preview=ref<{rows:{row_number:number;reference_no:string;title:string;valid:boolean;errors:string[]}[];valid_count:number;invalid_count:number}|null>(null),history=ref<{id:string;filename:string;total:number;created_at:string}[]>([]),page=ref(1),total=ref(0)
let worker:Worker|undefined,timer:ReturnType<typeof setTimeout>|undefined,rejectParse:((e:Error)=>void)|undefined
function stop(){clearTimeout(timer);worker?.terminate();worker=undefined;rejectParse?.(new RequestCancelled());rejectParse=undefined;parsing.value=false}
async function load(target=page.value){const result=await requests.latest<{items:typeof history.value;total:number}>('batches',`/intelligence/imports/batches?page=${target}`);history.value=result.items;page.value=target;total.value=result.total}
async function choose(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(input.value)input.value.value='';if(!file)return;error.value='';notice.value='';if(!file.name.endsWith('.xlsx')||file.size>2*1024*1024){error.value='仅支持 2 MB 以内的 .xlsx 文件';return}busy.value=true;parsing.value=true;const valid=captureSession();try{const buffer=await file.arrayBuffer();const values=await new Promise<ClueRow[]>((resolve,reject)=>{rejectParse=reject;worker=new Worker(new URL('./importSpreadsheet.worker.ts',import.meta.url),{type:'module'});timer=setTimeout(()=>{worker?.terminate();reject(new Error('Excel 解析超过 20 秒，已停止'))},20000);worker.onmessage=event=>event.data.error?reject(new Error(event.data.error)):resolve(event.data.rows);worker.onerror=()=>reject(new Error('Excel 解析失败'));worker.postMessage({buffer},[buffer])});if(!valid())return;rows.value=values;filename.value=file.name;preview.value=await requests.latest('preview','/intelligence/imports/preview',{method:'POST',body:JSON.stringify({filename:file.name,rows:values})})}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'预览失败'}finally{clearTimeout(timer);worker?.terminate();worker=undefined;rejectParse=undefined;busy.value=false;parsing.value=false}}
async function confirm(){busy.value=true;error.value='';const valid=captureSession();try{const response=await command('clue-excel-import','/intelligence/imports/confirm',{filename:filename.value,rows:rows.value}) as {imported:number};if(!valid())return;notice.value=`已导入 ${response.imported} 条线索，均为待核验状态`;preview.value=null;rows.value=[];await load(1);emit('imported')}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'导入失败'}finally{busy.value=false}}
async function download(){error.value='';try{const buffer=await template();const url=URL.createObjectURL(new Blob([buffer as BlobPart],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const link=document.createElement('a');link.href=url;link.download='情报线索导入模板.xlsx';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{error.value='模板生成失败'}}
onMounted(()=>{void load().catch(e=>{if(!isCancelled(e))error.value=e instanceof Error?e.message:'记录加载失败'})});onBeforeUnmount(()=>{requests.dispose();stop()})
</script>
<template><div class="page-list flow-import-panel"><section class="card"><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><div class="actions"><button :disabled="busy" @click="input?.click()">导入 Excel</button><button class="secondary" :disabled="busy" @click="download">下载线索模板</button><button v-if="parsing" class="secondary" @click="stop">取消解析</button><input ref="input" type="file" accept=".xlsx" hidden @change="choose"></div><p class="muted">每次最多 200 条、2 MB；线索编号在本组织内唯一，导入只新增待核验线索，不覆盖现有记录。重要线索下发时禁止派出所。</p><h2>导入记录</h2><div class="table-wrap"><table><thead><tr><th class="row-number">序号</th><th>文件名</th><th>导入数量</th><th>时间</th></tr></thead><tbody><tr v-for="(batch,index) in history" :key="batch.id"><td class="row-number">{{(page-1)*20+index+1}}</td><td>{{batch.filename}}</td><td>{{batch.total}}</td><td>{{formatTimestamp(batch.created_at)}}</td></tr></tbody></table><p v-if="!history.length" class="empty">暂无导入记录</p></div><Pagination :page="page" :total="total" :loading="busy" @change="load($event)"/></section><FormDialog v-if="preview" title="核对导入线索" :wide="true" :busy="busy" :error="error" @close="preview=null"><p>有效 {{preview.valid_count}} 条，错误 {{preview.invalid_count}} 条。存在错误时整批不入库，请修正文件后重新导入。</p><div class="table-wrap flow-import-preview"><table><thead><tr><th class="row-number">序号</th><th>Excel 行号</th><th>线索编号</th><th>标题</th><th>校验结果</th></tr></thead><tbody><tr v-for="(row,index) in preview.rows" :key="index"><td class="row-number">{{index+1}}</td><td>{{row.row_number}}</td><td>{{row.reference_no}}</td><td>{{row.title}}</td><td>{{row.errors.join('；')||'通过'}}</td></tr></tbody></table></div><button :disabled="busy||!!preview.invalid_count||!preview.valid_count" @click="confirm">确认导入 {{preview.valid_count}} 条线索</button></FormDialog></div></template>
